export const normalizePath = (path) => {
    if (!path)
        return "/";
    const withoutQuery = path.split("?")[0]?.split("#")[0] ?? "/";
    let next = withoutQuery;
    if (!next.startsWith("/")) {
        next = `/${next}`;
    }
    if (next !== "/" && next.endsWith("/")) {
        next = next.slice(0, -1);
    }
    return next;
};
export const getActiveHeaderPath = (menuLinks, currentPath) => {
    const normalizedCurrentPath = normalizePath(currentPath);
    let bestPath = "";
    let bestLength = -1;
    // For each header link, consider both its own path AND any declared
    // `subroutes` as match candidates. Subroutes let aliased detail
    // routes (e.g. `/people/<id>`) claim the right top-level menu item
    // (e.g. "Contributors" at `/contributors/`). Across all candidates,
    // the longest matching prefix wins — but the returned active path
    // is always `link.path` so the menu highlights the menu item itself.
    for (const link of menuLinks.filter((item) => item.inHeader)) {
        const candidatePaths = [link.path, ...(link.subroutes ?? [])];
        for (const candidate of candidatePaths) {
            const normalizedBasePath = normalizePath(candidate);
            const matches = (normalizedBasePath === "/" && normalizedCurrentPath === "/") ||
                (normalizedBasePath !== "/" &&
                    (normalizedCurrentPath === normalizedBasePath ||
                        normalizedCurrentPath.startsWith(`${normalizedBasePath}/`)));
            if (matches && normalizedBasePath.length > bestLength) {
                bestPath = link.path;
                bestLength = normalizedBasePath.length;
            }
        }
    }
    return bestPath;
};
